<div class="admin-heading"><div><span>آخر 30 يومًا</span><h1>التحليلات والتتبع</h1></div></div><div class="admin-grid"><section class="panel"><div class="panel-head"><h2>الأحداث</h2></div><div class="metric-list"><?php foreach($events as $e):?><div><span><?= e($e['event_name']) ?></span><strong><?= number_format($e['total']) ?></strong></div><?php endforeach; ?><?php if(!$events):?><p class="empty">لا توجد أحداث بعد.</p><?php endif; ?></div></section><section class="panel"><div class="panel-head"><h2>مصادر الزيارات</h2></div><div class="source-list"><?php $max=max(array_column($sources,'total')?:[1]);foreach($sources as $s):?><div><span><?= e($s['source']) ?><b><?= (int)$s['total'] ?></b></span><i style="--w:<?= ((int)$s['total']/$max)*100 ?>%"></i></div><?php endforeach;?></div></section></div><section class="panel chart-panel"><div class="panel-head"><h2>نشاط آخر 14 يومًا</h2></div><div class="bars"><?php $maxDay=max(array_column($days,'total')?:[1]);foreach($days as $d):?><div class="bar-item"><i style="--h:<?= ((int)$d['total']/$maxDay)*100 ?>%"><b><?= (int)$d['total'] ?></b></i><small><?= e(substr($d['day'],5)) ?></small></div><?php endforeach;?></div></section>